/** lib/sort.c, lines 225 to 260, verbatim. */
export const SORT_EXCERPT = {
  file: 'lib/sort.c',
  total: 357,
  start: 225,
  lines: [
    "\tfor (;;) {",
    "\t\tsize_t b, c, d;",
    "",
    "\t\tif (a)\t\t\t/* Building heap: sift down a */",
    "\t\t\ta -= size << shift;",
    "\t\telse if (n > 3 * size) { /* Sorting: Extract two largest elements */",
    "\t\t\tn -= size;",
    "\t\t\tdo_swap(base, base + n, size, swap_func, priv);",
    "\t\t\tshift = do_cmp(base + size, base + 2 * size, cmp_func, priv) <= 0;",
    "\t\t\ta = size << shift;",
    "\t\t\tn -= size;",
    "\t\t\tdo_swap(base + a, base + n, size, swap_func, priv);",
    "\t\t} else {\t\t/* Sort complete */",
    "\t\t\tbreak;",
    "\t\t}",
    "",
    "\t\t/*",
    "\t\t * Sift element at \"a\" down into heap.  This is the",
    "\t\t * \"bottom-up\" variant, which significantly reduces",
    "\t\t * calls to cmp_func(): we find the sift-down path all",
    "\t\t * the way to the leaves (one compare per level), then",
    "\t\t * backtrack to find where to insert the target element.",
    "\t\t *",
    "\t\t * Because elements tend to sift down close to the leaves,",
    "\t\t * this uses fewer compares than doing two per level",
    "\t\t * on the way down.  (A bit more than half as many on",
    "\t\t * average, 3/4 worst-case.)",
    "\t\t */",
    "\t\tfor (b = a; c = 2*b + size, (d = c + size) < n;)",
    "\t\t\tb = do_cmp(base + c, base + d, cmp_func, priv) > 0 ? c : d;",
    "\t\tif (d == n)\t/* Special case last leaf with no sibling */",
    "\t\t\tb = c;",
    "",
    "\t\t/* Now backtrack from \"b\" to the correct location for \"a\" */",
    "\t\twhile (b != a && do_cmp(base + a, base + b, cmp_func, priv) >= 0)",
    "\t\t\tb = parent(b, lsbit, size);",
  ],
};
